// The landing page and the hubs are static HTML generated by hand from one
// list, shared/site-map.json. This test fails when they drift apart: tile
// order and targets per group, the "N tools" group counts, the landing tile
// tags, the 110-character tile copy limit on the landing page, and the favicons,
// which are stamped from shared/favicon.template.svg with each family's
// --family-* colour from tokens.css.
//
//   node --test shared/tests/site-map.test.cjs
//   SITE_MAP_WRITE=1 node --test shared/tests/site-map.test.cjs   # rewrite the favicons from the template
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const { execFileSync } = require("node:child_process");

const root = path.resolve(__dirname, "../..");
const read = (file) => fs.readFileSync(path.join(root, file), "utf8");
const map = JSON.parse(read("shared/site-map.json"));
const tokens = read("shared/tokens.css");
const template = read("shared/favicon.template.svg").trim();

// Hubs built on shared/hub.css. Backgammon's hub belongs to its own family step.
const HUB_PAGES = map.families.filter((family) => !family.hub).map((family) => ({ family, file: `${family.id}/index.html` }));
const LANDING = "index.html";
const MAX_TILE_COPY = 110; // standard tiles: three lines at the 250px column minimum, under the four-line clamp everywhere wider than a phone
const MAX_FEATURED_COPY = 150; // featured tiles: three lines across a 30rem column

const text = (html) => html.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();
const decode = (s) => s.replace(/&amp;/g, "&").replace(/&nbsp;/g, " ");
const toolCount = (family) => family.groups.reduce((n, group) => n + group.tools.length, 0);

// The groups of a hub-style page: title, count text, tiles (href, heading) and link-list items.
function groups(html) {
  const sections = html.split(/<section class="group"/).slice(1);
  return sections.map((section) => {
    const head = section.match(/<div class="group-head">([\s\S]*?)<\/div>/);
    const [, title, count] = head[1].match(/<h2[^>]*>([\s\S]*?)<\/h2>\s*<span[^>]*>([\s\S]*?)<\/span>/);
    const tiles = Array.from(section.matchAll(/<a class="(tile[^"]*)" href="([^"]+)"[\s\S]*?<h3>([\s\S]*?)<\/h3>\s*<p>([\s\S]*?)<\/p>/g), (m) => ({ href: m[2], name: decode(text(m[3].replace(/<span class="visually-hidden">[\s\S]*?<\/span>/, ""))), featured: /tile--featured/.test(m[1]), copy: decode(text(m[4])) }));
    const links = Array.from(section.matchAll(/<ul class="hub-links">[\s\S]*?<\/ul>/g)).flatMap((list) =>
      Array.from(list[0].matchAll(/<a href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g), (m) => ({ href: m[1], name: decode(text(m[2].replace(/<span class="visually-hidden">[\s\S]*?<\/span>/, ""))) })),
    );
    const tags = Array.from(section.matchAll(/<div class="tags">([\s\S]*?)<\/div>/g), (m) => Array.from(m[1].matchAll(/<span>([^<]*)<\/span>/g), (t) => t[1]));
    return { title: decode(text(title)), count: decode(text(count)), tiles, links, tags };
  });
}



function familyColour(id) {
  const match = tokens.match(new RegExp(`--family-${id}:\\s*(#[0-9a-f]{6})`, "i"));
  assert.ok(match, `--family-${id} is defined in tokens.css`);
  return match[1];
}

function onAccent() {
  return tokens.match(/--on-accent:\s*(#[0-9a-f]{6})/i)[1];
}

// Pip layout of a die face on a 64px favicon, reused by the dice hub's art.
const PIPS = { 1: [[32, 32]], 2: [[20, 20], [44, 44]], 3: [[20, 20], [32, 32], [44, 44]], 4: [[20, 20], [44, 20], [20, 44], [44, 44]], 5: [[20, 20], [44, 20], [32, 32], [20, 44], [44, 44]], 6: [[20, 18], [44, 18], [20, 32], [44, 32], [20, 46], [44, 46]] };

function mark(glyph, ink) {
  const pips = glyph.match(/^pips:([1-6])$/);
  if (pips) return `<g fill="${ink}">${PIPS[pips[1]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="5.5"/>`).join("")}</g>`;
  const size = glyph.length > 1 ? 26 : 48;
  const y = glyph.length > 1 ? 41 : 49;
  return `<text x="32" y="${y}" font-family="Inter, system-ui, sans-serif" font-size="${size}" font-weight="800" text-anchor="middle" fill="${ink}">${glyph}</text>`;
}

function favicon(id, glyph) {
  const svg = template.replace("{{accent}}", familyColour(id)).replace("{{mark}}", mark(glyph, onAccent()));
  const encoded = svg.replace(/"/g, "'").replace(/[<>#%{}]/g, (c) => "%" + c.charCodeAt(0).toString(16).toUpperCase());
  return `data:image/svg+xml,${encoded}`;
}

const ICON = /<link rel="icon" href="([^"]+)" \/>/;

function copyFits(tile) {
  const limit = tile.featured ? MAX_FEATURED_COPY : MAX_TILE_COPY;
  assert.ok(tile.copy.length <= limit, `${tile.name}: tile copy under ${limit} characters: "${tile.copy}" (${tile.copy.length})`);
}

test("site-map.json is well formed", () => {
  const paths = new Set();
  for (const family of map.families) {
    assert.match(family.path, /^\/[a-z-]+\/$/, family.id);
    assert.ok(family.groups.length, `${family.id} has groups`);
    for (const group of family.groups)
      for (const tool of group.tools) {
        assert.ok(tool.path.startsWith(family.path), `${tool.name} lives under ${family.path}`);
        assert.ok(!paths.has(tool.path), `${tool.path} is listed once`);
        paths.add(tool.path);
      }
  }
  assert.deepEqual(
    map.families.map((family) => family.id),
    ["ofc", "poker", "blackjack", "backgammon", "dice"],
    "families in switcher order",
  );
});

for (const { family, file } of HUB_PAGES) {
  test(`${file} lists the ${family.name} tools from site-map.json`, () => {
    const html = read(file);
    assert.match(html, new RegExp(`<html lang="en" data-family="${family.id}">`), "data-family");
    const found = groups(html);
    const tileGroups = found.filter((group) => group.tiles.length);
    assert.deepEqual(tileGroups.map((group) => group.title), family.groups.map((group) => group.title), "group titles");
    family.groups.forEach((group, index) => {
      const page = tileGroups[index];
      assert.deepEqual(page.tiles.map(({ href, name }) => ({ href, name })), group.tools.map((tool) => ({ href: tool.path, name: tool.name })), `${group.title} tiles`);
      const unit = group.unit || "tool";
      const expected = `${group.tools.length} ${group.tools.length === 1 ? unit.replace(/s$/, "") : unit.endsWith("s") ? unit : unit + "s"}`;
      assert.equal(page.count, expected, `${group.title} count`);
    });
    if (family.links) {
      const list = found.find((group) => group.links.length);
      assert.ok(list, `${family.id} has a link list`);
      assert.equal(list.title, family.links.title);
      assert.deepEqual(list.links, family.links.items.map((item) => ({ href: item.href, name: item.name })), "link list");
      assert.equal(list.tiles.length, 0, "reference links are a list, not tiles");
      assert.equal(list.count, `${family.links.items.length} link${family.links.items.length === 1 ? "" : "s"}`);
    }
    for (const group of found) for (const tile of group.tiles) copyFits(tile);
  });
}

test("index.html lists every family, app and source project in site-map order", () => {
  const html = read(LANDING);
  const [hubs, apps, source] = groups(html);
  assert.deepEqual(hubs.tiles.map((tile) => tile.href), map.families.map((family) => family.path), "hub tiles");
  assert.deepEqual(apps.tiles.map((tile) => tile.href), map.apps.map((app) => app.path), "app tiles");
  assert.deepEqual(apps.tiles.map((tile) => tile.name), map.apps.map((app) => app.name), "app names");
  assert.deepEqual(source.links, map.source.map((item) => ({ href: item.href, name: item.name })), "source-only projects are a link list");
  assert.equal(source.tiles.length, 0, "an external GitHub link looks like a link, not an app tile");
  assert.equal(hubs.count, `${map.families.length} hubs`);
  assert.equal(apps.count, `${map.apps.length} apps`);
  assert.equal(source.count, `${map.source.length} project${map.source.length === 1 ? "" : "s"}`);
  hubs.tags.forEach((tags, index) => {
    const family = map.families[index];
    for (const tag of tags) {
      const count = tag.match(/^(\d+) tools?$/);
      if (count) assert.equal(Number(count[1]), toolCount(family), `${family.name} tile says ${tag}`);
    }
  });
  for (const group of [hubs, apps, source]) for (const tile of group.tiles) copyFits(tile);
  const stagger = Array.from(html.matchAll(/class="tile[^"]*"[^>]*style="--i: (\d+)/g), (m) => Number(m[1]));
  assert.deepEqual(stagger, stagger.map((_, i) => i), "tile stagger indices run 0..n without repeats");
  assert.ok(!/class="go"[^>]*>→/.test(html), "one arrow glyph: the SVG arrow, never a text arrow");
  assert.ok(!/class="go"[^>]*>\s*<svg[^>]*>\s*<line x1="7" y1="17"/.test(html), "one arrow glyph: no diagonal external arrow on a tile");
  assert.ok(!/<a class="tile[^"]*"[^>]*target="_blank"/.test(html), "no tile opens an external site");
  assert.ok(!/<img[^>]*style=/.test(html), "tile art images carry no inline style");
});

test("hub.css never ellipsises tile copy that fits the budget", () => {
  // 110 characters need up to four lines once the landing hub row or a
  // three-column tablet narrows the paragraph below 250px, and the phone list
  // has room for all of it; see the .tile p rules in shared/hub.css.
  const css = read("shared/hub.css").replace(/\/\*[\s\S]*?\*\//g, "");
  const clamps = Array.from(css.matchAll(/-webkit-line-clamp:\s*(\d+)/g), (m) => Number(m[1]));
  assert.ok(clamps.length, "the standard tile clamp exists");
  assert.ok(clamps.every((lines) => lines >= 3), `every clamp allows at least three lines (${clamps.join(", ")})`);
  const standard = css.match(/\n\.tile p \{([^}]*)\}/);
  assert.ok(standard && /-webkit-line-clamp:\s*4/.test(standard[1]), ".tile p clamps at four lines");
  const phones = css.slice(css.lastIndexOf("@media (max-width: 640px)"));
  const phoneCopy = phones.match(/\n  \.tile p \{([^}]*)\}/);
  assert.ok(phoneCopy && /display:\s*block/.test(phoneCopy[1]) && !/line-clamp/.test(phoneCopy[1]), "the phone list does not clamp tile copy");
});

test("every hub favicon is the template filled with its family colour", () => {
  const pages = [...HUB_PAGES.map(({ family, file }) => ({ id: family.id, glyph: family.glyph, file })), { id: "home", glyph: "MS", file: LANDING }];
  const write = !!process.env.SITE_MAP_WRITE;
  for (const page of pages) {
    const html = read(page.file);
    const expected = favicon(page.id, page.glyph);
    const current = html.match(ICON);
    assert.ok(current, `${page.file} has a favicon link`);
    if (write && current[1] !== expected) {
      fs.writeFileSync(path.join(root, page.file), html.replace(ICON, `<link rel="icon" href="${expected}" />`));
      console.log(`favicon written to ${page.file}`);
      continue;
    }
    assert.equal(current[1], expected, `${page.file} favicon follows --family-${page.id} (run with SITE_MAP_WRITE=1 to restamp)`);
  }
});

test("every hub has one footer, one switcher order, a skip link and main#main", () => {
  for (const file of [LANDING, ...HUB_PAGES.map((page) => page.file)]) {
    const html = read(file);
    assert.match(html, /<a class="skip-link" href="#main">Skip to content<\/a>/, `${file} skip link`);
    assert.match(html, /<main id="main" tabindex="-1">/, `${file} main#main`);
    assert.match(html, /<footer class="foot">\s*<nav class="foot-links" aria-label="Site">/, `${file} footer`);
    assert.match(html, /<meta name="theme-color" content="#08090d" \/>/, `${file} theme-color`);
    assert.doesNotMatch(html, /user-scalable=no/, `${file} allows zoom`);
    for (const shared of ["tokens.css", "app.css", "hub.css", "hub-art.css"]) assert.match(html, new RegExp(`shared/${shared}\\?v=20261016`), `${file} links ${shared} with the shared cache-bust`);
  }
});
